// Clic · fondos comerciales sin texto con FLUX (Together AI).
// La IA genera SOLO el fondo (sin producto, sin texto). Clic pone encima la foto real del producto,
// el logo y los textos como capas editables en el editor visual.
const input = $json.body ?? $json;
const requestId = String(input.requestId ?? input.id ?? Date.now());
const product = input.product ?? {};
const content = input.content ?? {};
const business = input.business ?? {};

// Modelo de Together AI. FLUX.1-schnell es rápido y barato; cámbialo aquí si usas otro.
const MODEL = 'black-forest-labs/FLUX.1-schnell';

const state = $getWorkflowStaticData('global');
state.jobs ??= {};
// Borra trabajos de más de 2 horas para que la memoria de n8n no crezca sin límite.
const expiry = Date.now() - 2 * 60 * 60 * 1000;
for (const [id, job] of Object.entries(state.jobs)) if (Date.parse(job.createdAt || 0) < expiry) delete state.jobs[id];
state.jobs[requestId] = { status: 'processing', createdAt: new Date().toISOString() };

const clean = (value, max) => String(value ?? '').replace(/\s+/g, ' ').trim().slice(0, max);
const subject = [clean(product.name, 80), clean(product.description, 200)].filter(Boolean).join(': ') || 'a small business product';
const style = clean(content.style, 30) || 'Moderno';
const colors = [content.colors?.primary || business.primary, content.colors?.background || business.secondary].filter(Boolean).map(c => clean(c, 9));
const instructions = clean(content.instructions, 300);

const NO_TEXT = 'Absolutely no text of any kind: no letters, no words, no numbers, no prices, no logos, no watermarks, no signs, no labels, no price tags, no captions, no typography anywhere in the image.';
const base = [
  'Professional commercial advertising background photograph for a social media post about ' + subject + '.',
  'Style: ' + style.toLowerCase() + ', premium, clean and inviting, soft natural studio lighting, shallow depth of field, high quality photography.',
  colors.length ? 'Color palette inspired by ' + colors.join(' and ') + '.' : '',
  instructions ? 'Extra direction (ignore any request to add text): ' + instructions + '.' : '',
  'This is an EMPTY scene: do not show the product itself, no people, no hands.',
];
// Composición por formato: deja libre donde Clic coloca la foto real y los textos.
const formats = [
  { network: 'instagram', width: 1024, height: 1024, layout: 'Square composition: an empty display surface (table, podium or shelf) in the center of the frame where the product will be placed later; calm, uncluttered top area; soft, low-detail lower third with plain surfaces for text overlays.' },
  { network: 'facebook', width: 1344, height: 704, layout: 'Wide landscape composition: an empty display surface on the left half of the frame where the product will be placed later; the right half plain, soft and uncluttered (negative space) for text overlays.' },
  { network: 'whatsapp', width: 768, height: 1344, layout: 'Tall vertical composition: an empty display surface in the upper middle of the frame where the product will be placed later; the lower 40% calm, plain and low-detail (negative space) for text overlays.' },
].map(format => ({ ...format, model: MODEL, ticket_id: requestId, prompt: [...base, format.layout, NO_TEXT].filter(Boolean).join(' ') }));

return [{ json: { ticket_id: requestId, status: 'processing', formats } }];

// Junta los tres fondos y los deja listos para /webhook/status.
const ticket = $('Initialize Job').first().json.ticket_id;
const formats = $('Split Formats').all().map(item => item.json);
const state = $getWorkflowStaticData('global');
state.jobs ??= {};
const mime = b64 => b64.startsWith('/9j/') ? 'image/jpeg' : b64.startsWith('iVBOR') ? 'image/png' : b64.startsWith('UklGR') ? 'image/webp' : 'image/jpeg';
const finalUrls = {};
const errors = [];
$input.all().forEach((item, index) => {
  const network = formats[index]?.network || 'instagram';
  const image = item.json?.data?.[0];
  const b64 = image?.b64_json || image?.base64;
  if (b64) finalUrls[network] = 'data:' + mime(b64) + ';base64,' + b64;
  else if (image?.url) finalUrls[network] = image.url;
  else errors.push(network + ': ' + (item.json?.error?.message || item.json?.error || 'Together AI no devolvió imagen'));
});
const finalUrl = finalUrls.instagram || Object.values(finalUrls)[0] || null;
state.jobs[ticket] = {
  ...(state.jobs[ticket] || {}),
  status: finalUrl ? 'completed' : 'error',
  // background = solo fondo (sin producto ni texto); Clic compone el producto real y los textos encima.
  kind: 'background',
  finalUrl,
  finalUrls,
  error: finalUrl ? (errors.length ? errors.join(' | ') : null) : (errors.join(' | ') || 'No se generó ninguna imagen.'),
  completedAt: new Date().toISOString(),
};
return [{ json: { ticket_id: ticket, status: state.jobs[ticket].status, generated: Object.keys(finalUrls), error: state.jobs[ticket].error } }];

const ticketId = String($json.query?.ticket_id ?? $json.ticket_id ?? '');
const state = $getWorkflowStaticData('global');
const job = state.jobs?.[ticketId];
return [{ json: job ? { ...job, ticket_id: ticketId } : { status: 'processing', ticket_id: ticketId } }];
